insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('9fbbea53-1923-4e7c-8fae-2dfdd469d0fd', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', null, 'topic'::public.curated_course_node_type, 'Probability spaces', 'This module establishes probability spaces as the course''s first working framework. It supplies the language and representations needed before the path advances to random variables as measurable maps.', 0),
  ('73006d0e-da95-4544-82ec-feed299b48e1', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', '9fbbea53-1923-4e7c-8fae-2dfdd469d0fd', 'subtopic'::public.curated_course_node_type, 'Sigma-algebras', 'Sigma-algebras identifies a specific object, distinction, or relationship within probability spaces. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before measures because that next topic assumes this starting point.', 0),
  ('b2e867f7-ef9f-4132-8be7-a4ecb271b54a', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', '9fbbea53-1923-4e7c-8fae-2dfdd469d0fd', 'subtopic'::public.curated_course_node_type, 'Measures', 'Measures identifies a specific object, distinction, or relationship within probability spaces. Learners need to recognize and use it before combining this module''s ideas in later work. After sigma-algebras, measures supplies what is needed to address continuity properties.', 1),
  ('2df542cc-cf4b-460f-adfc-1d3f7e17fb05', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', '9fbbea53-1923-4e7c-8fae-2dfdd469d0fd', 'subtopic'::public.curated_course_node_type, 'Continuity properties', 'Continuity properties identifies a specific object, distinction, or relationship within probability spaces. Learners need to recognize and use it before combining this module''s ideas in later work. After measures, continuity properties supplies what is needed to address modeling.', 2),
  ('697e2929-c036-4aa5-9fe6-79cc279e7069', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', '9fbbea53-1923-4e7c-8fae-2dfdd469d0fd', 'subtopic'::public.curated_course_node_type, 'Modeling', 'Modeling gives probability spaces a reusable representation for organizing assumptions, variables, and relationships before analysis begins. As the final topic in this module, modeling carries the completed idea into random variables as measurable maps.', 3),
  ('64cc385c-4e35-46d1-9261-b289d25bc20b', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', null, 'topic'::public.curated_course_node_type, 'Random variables as measurable maps', 'This module builds directly on probability spaces and develops random variables as measurable maps. It belongs here because its methods and distinctions are prerequisites for integration and expectation.', 1),
  ('ff4e8b60-aa61-47da-9d15-29dea1f3eb15', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', '64cc385c-4e35-46d1-9261-b289d25bc20b', 'subtopic'::public.curated_course_node_type, 'Distributions', 'Distributions gives random variables as measurable maps a reusable representation for organizing assumptions, variables, and relationships before analysis begins. It appears before cdfs because that next topic assumes this starting point.', 0),
  ('06f82c0d-442c-4ecd-9131-0921230b451c', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', '64cc385c-4e35-46d1-9261-b289d25bc20b', 'subtopic'::public.curated_course_node_type, 'CDFs', 'CDFs identifies a specific object, distinction, or relationship within random variables as measurable maps. Learners need to recognize and use it before combining this module''s ideas in later work. After distributions, cdfs supplies what is needed to address pushforward viewpoint.', 1),
  ('ca36956a-ac29-4388-8e6c-78da3a52d680', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', '64cc385c-4e35-46d1-9261-b289d25bc20b', 'subtopic'::public.curated_course_node_type, 'Pushforward viewpoint', 'Pushforward viewpoint identifies a specific object, distinction, or relationship within random variables as measurable maps. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, pushforward viewpoint carries the completed idea into integration and expectation.', 2),
  ('157bb0f0-8362-4ede-ac6b-74c7eb52f420', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', null, 'topic'::public.curated_course_node_type, 'Integration and expectation', 'This module builds directly on random variables as measurable maps and develops integration and expectation. It belongs here because its methods and distinctions are prerequisites for discrete and continuous families.', 2),
  ('4dc849bc-4952-47a9-8c09-458bdf4f37e3', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', '157bb0f0-8362-4ede-ac6b-74c7eb52f420', 'subtopic'::public.curated_course_node_type, 'Lebesgue expectation', 'Lebesgue expectation identifies a specific object, distinction, or relationship within integration and expectation. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before inequalities because that next topic assumes this starting point.', 0),
  ('0e40275f-6c20-4f92-a06c-8d3dfdda5767', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', '157bb0f0-8362-4ede-ac6b-74c7eb52f420', 'subtopic'::public.curated_course_node_type, 'Inequalities', 'Inequalities identifies a specific object, distinction, or relationship within integration and expectation. Learners need to recognize and use it before combining this module''s ideas in later work. After lebesgue expectation, inequalities supplies what is needed to address tail integrals.', 1),
  ('ec9aaa0a-a67e-4fe5-a05c-89b42ef0d08d', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', '157bb0f0-8362-4ede-ac6b-74c7eb52f420', 'subtopic'::public.curated_course_node_type, 'Tail integrals', 'Tail integrals identifies a specific object, distinction, or relationship within integration and expectation. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, tail integrals carries the completed idea into discrete and continuous families.', 2),
  ('8817cb4d-c972-4b14-a387-9cc7b61353b2', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', null, 'topic'::public.curated_course_node_type, 'Discrete and continuous families', 'This module builds directly on integration and expectation and develops discrete and continuous families. It belongs here because its methods and distinctions are prerequisites for joint distributions.', 3),
  ('c0731e86-5e75-4527-84da-18e18be291a0', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', '8817cb4d-c972-4b14-a387-9cc7b61353b2', 'subtopic'::public.curated_course_node_type, 'Exponential families', 'Exponential families identifies a specific object, distinction, or relationship within discrete and continuous families. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before transformations because that next topic assumes this starting point.', 0),
  ('21760f0e-a717-4e4b-8fa5-cb82618a475d', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', '8817cb4d-c972-4b14-a387-9cc7b61353b2', 'subtopic'::public.curated_course_node_type, 'Transformations', 'Transformations makes difficult behavior in discrete and continuous families tractable while exposing the assumptions and accuracy limits used by later methods. After exponential families, transformations supplies what is needed to address mixtures.', 1),
  ('d6b7c097-3a15-4cb5-9026-577b84fa272b', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', '8817cb4d-c972-4b14-a387-9cc7b61353b2', 'subtopic'::public.curated_course_node_type, 'Mixtures', 'Mixtures identifies a specific object, distinction, or relationship within discrete and continuous families. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, mixtures carries the completed idea into joint distributions.', 2),
  ('4b948c6f-bd92-4699-b78e-3d14ef679ea7', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', null, 'topic'::public.curated_course_node_type, 'Joint distributions', 'This module builds directly on discrete and continuous families and develops joint distributions. It belongs here because its methods and distinctions are prerequisites for conditional expectation.', 4),
  ('695f5649-640b-42a9-aee9-60dee660c02c', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', '4b948c6f-bd92-4699-b78e-3d14ef679ea7', 'subtopic'::public.curated_course_node_type, 'Product spaces', 'Product spaces gives joint distributions a reusable representation for organizing assumptions, variables, and relationships before analysis begins. It appears before independence because that next topic assumes this starting point.', 0),
  ('dffbb770-9e44-4b7c-9d5b-b08ff951c68e', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', '4b948c6f-bd92-4699-b78e-3d14ef679ea7', 'subtopic'::public.curated_course_node_type, 'Independence', 'Independence identifies a specific object, distinction, or relationship within joint distributions. Learners need to recognize and use it before combining this module''s ideas in later work. After product spaces, independence supplies what is needed to address covariance.', 1),
  ('12c10e05-f054-40d9-95b6-ad3127bee9b3', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', '4b948c6f-bd92-4699-b78e-3d14ef679ea7', 'subtopic'::public.curated_course_node_type, 'Covariance', 'Covariance identifies a specific object, distinction, or relationship within joint distributions. Learners need to recognize and use it before combining this module''s ideas in later work. After independence, covariance supplies what is needed to address change of variables.', 2),
  ('2063282f-fad9-4e41-a2f3-befee9ba2d33', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', '4b948c6f-bd92-4699-b78e-3d14ef679ea7', 'subtopic'::public.curated_course_node_type, 'Change of variables', 'Change of variables identifies a specific object, distinction, or relationship within joint distributions. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, change of variables carries the completed idea into conditional expectation.', 3),
  ('cdd99bc7-16c0-4ff2-91ce-dbe73002d293', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', null, 'topic'::public.curated_course_node_type, 'Conditional expectation', 'This module builds directly on joint distributions and develops conditional expectation. It belongs here because its methods and distinctions are prerequisites for transforms.', 5),
  ('1550d79a-e34b-44c2-bf95-304db0b2dc8a', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', 'cdd99bc7-16c0-4ff2-91ce-dbe73002d293', 'subtopic'::public.curated_course_node_type, 'Conditioning on events/variables', 'Conditioning on events/variables identifies a specific object, distinction, or relationship within conditional expectation. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before tower property because that next topic assumes this starting point.', 0),
  ('35b2bad7-2370-412d-9123-d4b54cb1f90b', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', 'cdd99bc7-16c0-4ff2-91ce-dbe73002d293', 'subtopic'::public.curated_course_node_type, 'Tower property', 'Tower property identifies a specific object, distinction, or relationship within conditional expectation. Learners need to recognize and use it before combining this module''s ideas in later work. After conditioning on events/variables, tower property supplies what is needed to address projection view.', 1),
  ('1601afbc-f904-463e-992c-cf223dd7b194', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', 'cdd99bc7-16c0-4ff2-91ce-dbe73002d293', 'subtopic'::public.curated_course_node_type, 'Projection view', 'Projection view identifies a specific object, distinction, or relationship within conditional expectation. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, projection view carries the completed idea into transforms.', 2),
  ('1d651f85-83ca-4052-b4fa-c2f27cc09468', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', null, 'topic'::public.curated_course_node_type, 'Transforms', 'This module builds directly on conditional expectation and develops transforms. It belongs here because its methods and distinctions are prerequisites for modes of convergence.', 6),
  ('ee958710-6bab-47cf-97d1-0b09544907a3', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', '1d651f85-83ca-4052-b4fa-c2f27cc09468', 'subtopic'::public.curated_course_node_type, 'Generating functions', 'Generating functions identifies a specific object, distinction, or relationship within transforms. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before characteristic functions because that next topic assumes this starting point.', 0),
  ('6e3d8a9c-8019-4ecc-b6f9-0733b6c25ce3', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', '1d651f85-83ca-4052-b4fa-c2f27cc09468', 'subtopic'::public.curated_course_node_type, 'Characteristic functions', 'Characteristic functions identifies a specific object, distinction, or relationship within transforms. Learners need to recognize and use it before combining this module''s ideas in later work. After generating functions, characteristic functions supplies what is needed to address uniqueness.', 1),
  ('87938e36-c0d8-4f72-a6f3-dbd0158e7d6d', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', '1d651f85-83ca-4052-b4fa-c2f27cc09468', 'subtopic'::public.curated_course_node_type, 'Uniqueness', 'Uniqueness identifies a specific object, distinction, or relationship within transforms. Learners need to recognize and use it before combining this module''s ideas in later work. After characteristic functions, uniqueness supplies what is needed to address sums.', 2),
  ('63cc7fa9-e662-4fb3-bd57-6dbdf8d2180c', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', '1d651f85-83ca-4052-b4fa-c2f27cc09468', 'subtopic'::public.curated_course_node_type, 'Sums', 'Sums identifies a specific object, distinction, or relationship within transforms. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, sums carries the completed idea into modes of convergence.', 3),
  ('54e3bc57-3470-4542-977a-afe3c8eca45f', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', null, 'topic'::public.curated_course_node_type, 'Modes of convergence', 'This module builds directly on transforms and develops modes of convergence. It belongs here because its methods and distinctions are prerequisites for laws of large numbers.', 7),
  ('ca670da7-fd6c-4b3b-9523-2d1672ac2a5f', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', '54e3bc57-3470-4542-977a-afe3c8eca45f', 'subtopic'::public.curated_course_node_type, 'Almost sure', 'Almost sure identifies a specific object, distinction, or relationship within modes of convergence. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before probability because that next topic assumes this starting point.', 0),
  ('f5f5c1ac-b669-493a-a9f4-17139703de96', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', '54e3bc57-3470-4542-977a-afe3c8eca45f', 'subtopic'::public.curated_course_node_type, 'Probability', 'Probability is a governing quantity in modes of convergence, linking local calculations to system-level behavior and offering a consistency check. After almost sure, probability supplies what is needed to address lp.', 1),
  ('c82cda27-a2b0-4666-8737-300049de221a', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', '54e3bc57-3470-4542-977a-afe3c8eca45f', 'subtopic'::public.curated_course_node_type, 'Lp', 'Lp identifies a specific object, distinction, or relationship within modes of convergence. Learners need to recognize and use it before combining this module''s ideas in later work. After probability, lp supplies what is needed to address distribution.', 2),
  ('c036224a-f34a-4c91-89f9-9646adf785f0', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', '54e3bc57-3470-4542-977a-afe3c8eca45f', 'subtopic'::public.curated_course_node_type, 'Distribution', 'Distribution gives modes of convergence a reusable representation for organizing assumptions, variables, and relationships before analysis begins. After lp, distribution supplies what is needed to address implications.', 3),
  ('d7efa34c-c8c4-4ced-b9d1-0800d699e086', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', '54e3bc57-3470-4542-977a-afe3c8eca45f', 'subtopic'::public.curated_course_node_type, 'Implications', 'Implications identifies a specific object, distinction, or relationship within modes of convergence. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, implications carries the completed idea into laws of large numbers.', 4),
  ('975a8a9b-277f-4bfe-a85d-8aba741c47d9', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', null, 'topic'::public.curated_course_node_type, 'Laws of large numbers', 'This module builds directly on modes of convergence and develops laws of large numbers. It belongs here because its methods and distinctions are prerequisites for central limit theorem.', 8),
  ('d534ac80-5cba-4964-b67e-edd257bfdcb9', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', '975a8a9b-277f-4bfe-a85d-8aba741c47d9', 'subtopic'::public.curated_course_node_type, 'Weak/strong forms', 'Weak/strong forms identifies a specific object, distinction, or relationship within laws of large numbers. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before borel–cantelli tools because that next topic assumes this starting point.', 0),
  ('724894af-eec0-4a1e-bfb7-9819ae4b4f84', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', '975a8a9b-277f-4bfe-a85d-8aba741c47d9', 'subtopic'::public.curated_course_node_type, 'Borel–Cantelli tools', 'Borel–Cantelli tools identifies a specific object, distinction, or relationship within laws of large numbers. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, borel–cantelli tools carries the completed idea into central limit theorem.', 1);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('c51ea002-27dd-40de-ab24-0919781231f0', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', null, 'topic'::public.curated_course_node_type, 'Central limit theorem', 'This module builds directly on laws of large numbers and develops central limit theorem. It belongs here because its methods and distinctions are prerequisites for martingales.', 9),
  ('f4dfb39b-eb69-4a18-886d-2d49ad2ad299', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', 'c51ea002-27dd-40de-ab24-0919781231f0', 'subtopic'::public.curated_course_node_type, 'Characteristic-function proof ideas', 'Characteristic-function proof ideas provides a formal guarantee or inference rule for central limit theorem, allowing later conclusions to be justified rather than inferred from examples alone. It appears before delta-method glimpse because that next topic assumes this starting point.', 0),
  ('2f6d3601-84dd-4df2-9a67-a770dac0cca4', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', 'c51ea002-27dd-40de-ab24-0919781231f0', 'subtopic'::public.curated_course_node_type, 'Delta-method glimpse', 'Delta-method glimpse identifies a specific object, distinction, or relationship within central limit theorem. Learners need to recognize and use it before combining this module''s ideas in later work. As the final topic in this module, delta-method glimpse carries the completed idea into martingales.', 1),
  ('0b90c3f7-71cb-483e-a802-e28e61c90fb3', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', null, 'topic'::public.curated_course_node_type, 'Martingales', 'This module builds directly on central limit theorem and develops martingales. It belongs here because its methods and distinctions are prerequisites for stochastic processes.', 10),
  ('7dcefe48-5dce-4287-81d2-bbb1dd376777', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', '0b90c3f7-71cb-483e-a802-e28e61c90fb3', 'subtopic'::public.curated_course_node_type, 'Filtrations', 'Filtrations identifies a specific object, distinction, or relationship within martingales. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before stopping because that next topic assumes this starting point.', 0),
  ('7aef1496-f0ff-4671-b324-3a5bce368616', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', '0b90c3f7-71cb-483e-a802-e28e61c90fb3', 'subtopic'::public.curated_course_node_type, 'Stopping', 'Stopping identifies a specific object, distinction, or relationship within martingales. Learners need to recognize and use it before combining this module''s ideas in later work. After filtrations, stopping supplies what is needed to address convergence concepts.', 1),
  ('38676a8f-da07-433a-9f24-cc99c6465484', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', '0b90c3f7-71cb-483e-a802-e28e61c90fb3', 'subtopic'::public.curated_course_node_type, 'Convergence concepts', 'Convergence concepts makes difficult behavior in martingales tractable while exposing the assumptions and accuracy limits used by later methods. After stopping, convergence concepts supplies what is needed to address fair-game models.', 2),
  ('8d7127a1-4624-4507-be32-96ac6d14c3ff', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', '0b90c3f7-71cb-483e-a802-e28e61c90fb3', 'subtopic'::public.curated_course_node_type, 'Fair-game models', 'Fair-game models gives martingales a reusable representation for organizing assumptions, variables, and relationships before analysis begins. As the final topic in this module, fair-game models carries the completed idea into stochastic processes.', 3),
  ('7ab2256d-1882-40a0-83e8-c9d997e6df3c', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', null, 'topic'::public.curated_course_node_type, 'Stochastic processes', 'This culminating module draws on martingales and develops stochastic processes. It belongs last because it requires the earlier tools to be selected, combined, and evaluated rather than used one at a time.', 11),
  ('8a51574b-c98b-4000-a405-1e7d151935b7', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', '7ab2256d-1882-40a0-83e8-c9d997e6df3c', 'subtopic'::public.curated_course_node_type, 'Markov chains', 'Markov chains identifies a specific object, distinction, or relationship within stochastic processes. Learners need to recognize and use it before combining this module''s ideas in later work. It appears before poisson process because that next topic assumes this starting point.', 0),
  ('7aea2f61-f8ef-4ad7-b9e7-eddf1e39be5d', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', '7ab2256d-1882-40a0-83e8-c9d997e6df3c', 'subtopic'::public.curated_course_node_type, 'Poisson process', 'Poisson process gives stochastic processes a reusable representation for organizing assumptions, variables, and relationships before analysis begins. After markov chains, poisson process supplies what is needed to address brownian-motion introduction.', 1),
  ('3ce8e5fd-1669-4d05-98d0-fc7e8d7e3d5d', 'd6f6d154-68dc-44ec-aba6-f42263ebeea7', '7ab2256d-1882-40a0-83e8-c9d997e6df3c', 'subtopic'::public.curated_course_node_type, 'Brownian-motion introduction', 'Brownian-motion introduction identifies a specific object, distinction, or relationship within stochastic processes. Learners need to recognize and use it before combining this module''s ideas in later work. As the final course topic, brownian-motion introduction requires ideas from the complete path to be integrated and transferred.', 2);
insert into public.learning_paths (
